     1	package br.com.loja.pedidos.common;
     2	
     3	import java.math.BigDecimal;
     4	
     5	public enum Region {
     6	    SOUTHEAST("0.01", null, 0),
     7	    SOUTH("0.01", null, 0),
     8	    MIDWEST("0.015", null, 0),
     9	    NORTH("0.025", "30.00", 3),
    10	    NORTHEAST("0.02", "30.00", 2);
    11	
    12	    private final BigDecimal insuranceRate;
    13	    private final BigDecimal insuranceCap;
    14	    private final int carrierExtraDays;
    15	
    16	    Region(String insuranceRate, String insuranceCap, int carrierExtraDays) {
    17	        this.insuranceRate = new BigDecimal(insuranceRate);
    18	        this.insuranceCap = insuranceCap == null ? null : new BigDecimal(insuranceCap);
    19	        this.carrierExtraDays = carrierExtraDays;
    20	    }
    21	
