533	    13	
534	    14	    private static final int MAX_INSTALLMENTS = 12;
535	    15	    private static final int MAX_INTEREST_FREE_INSTALLMENTS = 3;
536	    16	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
537	    17	
538	    18	    @Override
539	    19	    public String code() {
540	    20	        return "CREDIT_CARD";
541	    21	    }
542	    22	
543	    23	    @Override
544	    24	    public boolean allowsInstallments(int installments) {
545	    25	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
546	    26	    }
547	    27	
548	    28	    @Override
549	    29	    public PaymentCharge charge(PaymentContext context) {
550	    30	        BigDecimal total = context.orderTotal();
551	    31	        int n = context.installments();
552	    32	        if (n <= MAX_INTEREST_FREE_INSTALLMENTS) {
553	    33	            BigDecimal installment = Money.round(total.divide(BigDecimal.valueOf(n), 10, RoundingMode.HALF_EVEN));
554	    34	            return new PaymentCharge(total, installment);
555	    35	        }
556	    36	        // tabela Price: parcela = total * i / (1 - (1 + i)^-n)
557	    37	        MathContext mc = MathContext.DECIMAL128;
558	    38	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, mc);
559	    39	        BigDecimal discountFactor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, mc), mc);
560	    40	        BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE, mc).divide(discountFactor, mc));
561	    41	        return new PaymentCharge(installment.multiply(BigDecimal.valueOf(n)), installment);
562	    42	    }
